INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich die zeitliche Abfolge ohne Arbeitspakete planen?', 2, '[{"text": "Nein", "correct": true, "because": "Arbeitspakete sind die Basis"}, {"text": "Ja", "correct": false, "because": "Fehlende Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der zeitlichen Abfolge?', 3, '[{"text": "Projektkoordination", "correct": true, "because": "Synchronisiert Ablauf"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei der Zeitplanung?', 5, '[{"text": "Gantt-Diagramm", "correct": true, "because": "Visualisiert Abfolge"}, {"text": "Kritische Pfad Methode", "correct": true, "because": "Priorisiert Engpässe"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Unzuverlässig"}, {"text": "Manuelle Liste", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gantt-Diagramme zeigen Abhängigkeiten. b) Zeitpläne sind immer fix.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) flexibel anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Zeitplanung?', 4, '[{"text": "Abhängigkeiten", "correct": false, "because": "Bestimmt Reihenfolge"}, {"text": "Dauer", "correct": false, "because": "Definiert Zeitrahmen"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zeitpläne immer starr sind?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassungen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für ein Gantt-Diagramm?', 3, '[{"text": "MS Project", "correct": true, "because": "Erstellt Zeitpläne"}, {"text": "Notepad", "correct": false, "because": "Keine Visualisierung"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Zeitplanung effektiv?', 5, '[{"text": "Realistische Dauer", "correct": true, "because": "Vermeidet Verzögerungen"}, {"text": "Abhängigkeiten", "correct": true, "because": "Koordiniert Ablauf"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Zeitpläne sind nur für große Projekte. b) Abhängigkeiten sind unwichtig. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch kleine Projekte, Abhängigkeiten zentral"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Zeitplanung?', 4, '[{"text": "Arbeitspakete", "correct": false, "because": "Grundlage der Planung"}, {"text": "Meilensteine", "correct": false, "because": "Markiert Fortschritt"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Zeitplanung nur für den Start?', 2, '[{"text": "Nein", "correct": true, "because": "Laufende Anpassung nötig"}, {"text": "Ja", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infos sind für die Zeitplanung entscheidend?', 4, '[{"text": "Dauer", "correct": true, "because": "Bestimmt Zeitrahmen"}, {"text": "Abhängigkeiten", "correct": true, "because": "Definiert Reihenfolge"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Zeitpläne ohne Puffer auskommen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Puffer schützt Verzögerungen"}, {"text": "Ja", "correct": false, "because": "Risiko steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Zeitplanung?', 3, '[{"text": "Kritischer Pfad", "correct": true, "because": "Fokussiert Engpässe"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Unlogisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Meilensteine markieren Fortschritt. b) Zeitpläne sind unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Zeitplanung?', 5, '[{"text": "Übersicht", "correct": true, "because": "Klarer Ablauf"}, {"text": "Ressourcennutzung", "correct": true, "because": "Optimiert Einsatz"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Zeitplanung unwichtig?', 3, '[{"text": "Reihenfolge", "correct": false, "because": "Koordiniert Ablauf"}, {"text": "Pufferzeiten", "correct": false, "because": "Schützt Verzögerungen"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt die Zeitplanung die Ausführung?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Vorbereitung"}, {"text": "Ja", "correct": false, "because": "Ausführung separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zeitpläne nur für Teams sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Einzelprojekte"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Zeitplanung entscheidend?', 4, '[{"text": "Abhängigkeitserkennung", "correct": true, "because": "Sichert Ablauf"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Manuelle Schätzung", "correct": false, "because": "Ungenau"}]');